"""Stored Beam Service mode functions. These functions are called from the
top level IntegrityService interface. They are not intended to be called
directly from a test script"""

import interops.libraries.integrity.integrity_objects as IntegrityObjects
import interops.libraries.integrity.pages.service_screen as ServicePgObj
import interops.libraries.integrity.pages.storedbeam_menu as StoredBeamPgObj
from interops.libraries.integrity.sub_system_workflows.general_utility_funcs import _utility_close_all_open_applets
from typing import Optional as opt
import interops.libraries.desktop.decorators as deco
from interops.libraries.squish_actions.constants import INTEGRITY_APP_NAME
import squishtest3 as sq
import logging


logger = logging.getLogger(__name__)

@deco.set_separate_app_context(INTEGRITY_APP_NAME)
def _service_funcs_open_stored_beam_menu() -> bool:
    '''
    Open the Deliver Stored Beam menu page from the main
    Service Menu Bar via the Service Functions menu.

    Returns:
        bool - True if Stored Beam Menu opened successfully
    '''
    for n in range(2):
        try:
            logger.info("open_stored_beam_menu called.")
            service_menu = ServicePgObj.ServiceMenuBar()
            if service_menu.ready():
                service_menu.service_functions()

                service_funcs_menu = ServicePgObj.ServiceFunctionsMenuBar()
                service_funcs_menu.deliver_stored_beam()

                sq.waitForObjectExists(IntegrityObjects.dSB_Tab_General)
                sq.waitForObjectExists(IntegrityObjects.dSB_Combo_Sequences)

                return True
        except Exception:
            logger.info("open_stored_beam_menu failed")
    return False


@deco.set_separate_app_context(INTEGRITY_APP_NAME)
def _service_open_deliver_stored_beam_menu() -> StoredBeamPgObj.DeliverStoredBeam:
    '''
    Retrieve the DSB instance for RTDShell.

    Returns:
        DeliverStoredBeam - PageObject representing the DSB UI.
    '''
    service_funcs_menu = ServicePgObj.ServiceFunctionsMenuBar()
    stored_beam_menu = service_funcs_menu.deliver_stored_beam()

    return stored_beam_menu


@deco.set_separate_app_context(INTEGRITY_APP_NAME)
def _service_select_deliver_stored_beam_item(beam_name: str, set_sequence: opt[str]=None, num_of_attempts: int=3):
    '''
    Sets up Stored Beam by selecting the sequence and beam from the drop down lists
    Beam and sequence data is typically read from a CSV datasheet file

    Args:
        beam_name (str): Beam to select from Beams list
        set_sequence (str): Sequence to select from Sequences list
        num_of_attempts (int): No. of attempts to selecting from the lists

    '''
    stored_beam_menu = StoredBeamPgObj.DeliverStoredBeam()
    for i in range(num_of_attempts):
        if i == 2:
            logger.info("RESTARTING DSB APPLET BEFORE FINAL TRY")
            _utility_close_all_open_applets(close_buttons=[{"container": {"id": 201, "type": "Pane"}, "text": "X"}])
            sq.snooze(2)
            _service_funcs_open_stored_beam_menu()
        logger.info("SELECT DELIVER STORED BEAM ITEM TRY {}".format(str(i)))
        logger.info("IS INTEGRITY FROZEN:- {}".format(str(sq.currentApplicationContext().isFrozen(10))))
        stored_beam_menu.tab_general()
        stored_beam_menu.press_unconfirm()
        if set_sequence and sq.waitForObject(IntegrityObjects.dSB_Combo_Sequences)["text"] != set_sequence:
            logger.info("SEQUENCE IS SET " + str(stored_beam_menu.set_sequence(set_sequence)))

        if sq.waitForObject(IntegrityObjects.dSB_Combo_Sequences)["text"] in ("<None>", "None"):
            if i == 2:
                sq.mouseClick(sq.waitForObject(IntegrityObjects.dSB_Combo_Beams))
                logger.info("WAITING FOR 10 SECS FOR BEAM DROPDOWN LOAD")
                sq.snooze(10)
            else:
                sq.mouseClick(sq.waitForObject(IntegrityObjects.dSB_Combo_Beams))
            sq.snooze(1)
            if sq.object.exists({"type": "List", "className": "ComboLBox", "x": 137, "y": 110}):
                logger.info("DSB BEAM DROP DOWN OPEN")
                if not sq.waitForObject({"id": "NonClientVerticalScrollBar"}).position == 0:
                    sq.mousePress(sq.waitForObject({"text": "Line up", "id": "UpButton"}))
                    while True:
                        if sq.waitForObject({"id": "NonClientVerticalScrollBar"}).position == 0:
                            sq.mouseRelease(sq.waitForObject({"text": "Line up", "id": "UpButton"}))
                            break

                beam_found = False
                while not beam_found:
                    try:
                        logger.info("POSITION OF SCROLLBAR IS {}".format(
                            str(sq.waitForObject({"id": "NonClientVerticalScrollBar"}).position)))
                        if i == 2:
                            logger.info("INCREASING TIMEOUT TO 10 SECS FOR ITEM IN FINAL TRY")
                            sq.mouseClick(sq.waitForObject(
                                {"container": IntegrityObjects.dSB_Combo_Beams, "text": beam_name}, 10000))
                        else:
                            sq.mouseClick(sq.waitForObject(
                                {"container": IntegrityObjects.dSB_Combo_Beams, "text": beam_name}, 3000))
                        sq.snooze(1)
                        if sq.object.exists({"type": "List", "className": "ComboLBox", "x": 137, "y": 110}):
                            # try again if click not registered
                            logger.info("DROPDOWN still open trying to click item again")
                            sq.mouseClick(sq.waitForObject(
                                {"container": IntegrityObjects.dSB_Combo_Beams, "text": beam_name}, 5))
                        beam_found = True
                        break
                    except Exception as e:
                        if sq.waitForObject({"id": "NonClientVerticalScrollBar"}).position == 100:
                            logger.info("Beam name not in entire list, appears invalid" + str(e))
                            break
                        logger.info("Beam name not found in drop down" + str(e))
                        sq.mousePress(sq.waitForObject({"text": "Line down", "id": "DownButton"}))
                        sq.snooze(0.5)
                        sq.mouseRelease(sq.waitForObject({"text": "Line down", "id": "DownButton"}))

                stored_beam_menu.tab_general()
                if stored_beam_menu.check_set_stored_beam(beam_name, set_sequence):
                    return True

            else:
                stored_beam_menu.set_beams(beam_name)
                if stored_beam_menu.check_set_stored_beam(beam_name, set_sequence):
                    return True


@deco.set_separate_app_context(INTEGRITY_APP_NAME)
def _service_select_next_stored_beam(reset_to_start: bool=False) -> bool:
    '''
    Selects the next beam in the Deliver Stored Beam drop-down list

    Args:
        reset_to_start (bool): Resets to first item in the Beams list

    Returns:
        bool - True if the beam selected is different from the last beam
    '''
    LAST_BEAM = "none"
    try:
        stored_beam_menu = StoredBeamPgObj.DeliverStoredBeam()
        stored_beam_menu.tab_general()
        # dsb.press_next_beam()
        if reset_to_start:
            sq.mouseClick(sq.waitForObject(IntegrityObjects.dSB_Combo_Beams))
            sq.snooze(0.5)
            sq.nativeType("<Home>")
            sq.nativeType("<Return>")
            return True

        if stored_beam_menu.get_actual_dsb_sequence() in ("<None>", "None"):
            sq.mouseClick(sq.waitForObject(IntegrityObjects.dSB_Combo_Beams))
            sq.snooze(0.5)
            sq.nativeType("<Right>")
            sq.snooze(0.5)
            sq.nativeType("<Return>")
        sq.snooze(0.5)
        new_beam = stored_beam_menu.get_actual_dsb_beams()
        if new_beam == LAST_BEAM:
            return False
        LAST_BEAM = new_beam
        logger.info("next beam selected - " + new_beam)
        return True
    except Exception as e:
        logger.exception("select_next_stored_beam - " + str(e))
        return False